import { THEMES } from './replay-stories.js';
import { PEOPLE } from './data.js';
import { departureContactReason } from './separation-stories.js';
const TURNS={
 quiet:[
  ['只走到那把椅子','原来缩短的散步只到一把椅子。阿澈坐下才发现雨音其实还想再往里走，却一直没说。{guest}带来一张只画了半条路的小卡，没人能同时把两段都走完。','陪雨音再找一个转角，接受茶会这回不办','留在椅子旁，听阿澈讲他没带队的一晚','你们实际走到第二个转角，茶会没有发生；雨音回来时认真把新入口画了出来。','你们没有再赶路，阿澈终于讲完那次自己玩错机关的经历。更深处的风景留在未走的半张卡上。'],
  ['茶杯旁空着的座位','改过安排的小茶会开场了。阿澈准备了三个话题，雨音只想先听。{guest}拿来一张空白菜单，随口写了一个很离谱的节目名，气氛突然松了一点。','每人只讲一件小事，把节目取消','保留一个轻松小游戏，允许只旁听','三个原定话题被划掉，留下的都是当晚真的想讲的小事，空座位也没有被拿去凑满人数。','那个离谱节目成了一个很短的小游戏。雨音只旁听了一轮，后来自己补了一个答案。'],
  ['分头走却带回同一种树叶','你们分头探索后回来，雨音与阿澈竟然都在讲一片很普通的树叶。{guest}认真听了两种描述：一个记得声音，一个只记得颜色。共同发现并没有让两段独处变成同一段经历。','把两种描述并排收进旅行页','只交换这次最想讲的一句，不做共同记录','旅行页有了两种树叶，画的不是同一个形状。下一次打开时，仍能认出是谁先注意到了什么。','你们只交换了一句话。没有共同文档，也没有为了证明独处值得而补拍一张合照。'],
 ],
 workshop:[
  ['试展只剩一张台阶贴纸','缩小范围后的展览只修一个入口。零点与弥生分别画了台阶标记，{guest}第一次试走时偏偏踩在两张贴纸中间。“这不是贴得够不够漂亮的问题。”零点蹲下看了很久。','重做标记的间距，暂时拿掉装饰','保留原装饰，另留一条容易看清的短入口','标记重新排过以后，试走真的顺了，原来的装饰没有在这版展出。','短入口实际被走通，装饰版仍保留自己的限制，说明里清楚写了哪条路适合先试。'],
  ['过程墙上缺了一张图','调整过的过程墙撤下一张未获许可的草图，留下一个显眼的空框。弥生想用自己的新图补齐，零点却觉得缺口也该解释。{guest}停在空框前，问的是为什么这一格没有作品。','留下空框，只说明作者撤回了展示许可','另做自己的过程图，重新标明来源','空框没有泄露撤下的内容。访客知道了缺失的原因，也知道这段过程不属于展方可以代替公开的材料。','新图是弥生重新做的独立演示，旁边注明它并非撤下的那张。墙变了，也没有伪装成原过程从来完整。'],
  ['两个测试结果对不上','分头测试的最后一份结果彼此相反。{guest}带来另一台设备的反馈，零点发现自己没试过那种设置，弥生也不愿把无法复现的问题直接划掉。','只发布已经验证的设置说明','把两种结果并列，先做一份待验证的试展单','这一版明确只支持经过验证的范围，其他设备没有被顺手保证能用。','你们没有宣布通用完成，而是保存了两份真实反馈与可复现步骤，小展暂时按试展开放。'],
 ],
 gathering:[
  ['猜词牌只剩最后一格','简化过的猜词局只剩一格时间，阿澈还没轮到画，凛却想让一直旁听的人先来。{guest}举起一张乱画的牌，说自己其实也没准备好。最后一轮只能留给一个安排。','把最后一轮交给阿澈，其他人留到下次','改成共同画一笔，放弃原来的猜词计分','阿澈真的画完了一张很难猜的图。旁听者这晚没有被临时推到台前，也被单独认真道了晚安。','最后一张牌被几个人各添一笔，已经没法按原规则计分。大家接受这是另一种收尾。'],
  ['那首长歌还没播完','重排过的歌单遇到一首很长的曲子。凛听得投入，阿澈提醒最后的人还没有选歌，{guest}已经到了要下线的时间。没有一种排法能让所有曲子完整播完。','让最后的人先选一小段，长歌以后自己听','把长歌听完，其他选曲另发成私人清单','长歌在双方说明后暂停，最后的人真的放出自己最想分享的一段。没有谁被说成不懂欣赏。','长歌被听完，离开的人收到清单而非必须留下的要求。没播到的曲子也没被登记成已经共同听过。'],
  ['谁都不知道最后一个开关','分头探索的小队回到机关前，阿澈和凛的线索拼在一起仍少一块。{guest}提出可以去查答案，也说自己更想保留不知道的这一晚。','再试一次，只记录真实找到的线索','这回收工，给愿意查答案的人留单独入口','你们又试了一次，仍没通关，只多确认了一条不通的路。阿澈把它认真标出来，没有把失败藏掉。','小队这晚确实停了。想继续的人得到一个独立入口，其他人没有因为先走而失去下一次邀请的资格。'],
 ],
 letters:[
  ['结束提醒比话题先到了','限定时长的同行响起结束提醒。小满还有半句话，雨音已经很困，{guest}也在等一个明确的散场信号。喜欢再聊一会儿和真的需要休息挤在同一分钟里。','按原定时间结束，留下尚未讲完的一句话','重新问一次能否多聊一小段，拒绝就结束','提醒响后你们真的散场了。那半句话被保留下来，没有被随便补成后来一定说完的故事。','有人愿意，有人先离开。留下的人只多聊了重新确认的一小段，没有把这次同意变成以后的默认。'],
  ['第二次改期以前先停一下','允许变更的邀请又遇到调整。小满怕只剩日历在来回挪，雨音坦白自己现在确实给不出稳定的时段。{guest}问了一句：这次一定需要立刻补约吗？','先取消这份邀请，等安排稳定再重新询问','把相处缩成一次明确的短留言交换','这份卡片这次正式取消，失落被听见，也没有立即生成一个更大的保证。','你们只交换了各自愿意写的一小段近况，没有把文字交换冒充一次同时在线的赴约。'],
  ['回信迟到时说了什么','异步近况隔了几夜才有回信。雨音先解释自己为什么卡在第一行，小满却想知道能否至少确认已经看到。{guest}记得自己也曾把读过的消息误放成未读。','只确认收到，不规定完整回信期限','商量一个可拒绝的短回应方式','确认收到的一句很短，正文仍然可以以后再写。等待没有被改写成对方必须马上交出的作业。','两人各说了自己能做到与做不到的部分，留下一个可以拒绝的短回应方式，仍没有承诺永远及时。'],
 ],
 paths:[
  ['短路线少了最喜欢的声音','只保留复核段落后，凛最喜欢的一段声音被排除在短路线外。零点认为入口说明更急，{guest}则想知道能不能有一个自选绕行点。卡片已经没有位置把一切都放进去。','保留清楚的主入口，声音另做一张小卡','把声音作为可跳过的支路，缩短另一段说明','主卡更短，声音拥有自己的小卡，没有被说成每位访客都必须体验的重点。','支路被标成可选，另一段说明缩短后也明确留下了需要自己确认的范围。'],
  ['改过的路线又关了一扇门','改排过的路线碰到一扇暂时关闭的门。凛还记得门后的景色，零点想立即撤掉入口，{guest}只问现在到底还能不能走通。旧体验不能替今天的门作保证。','先撤下这段入口，保留历史记录','保留为旧路线注记，再画一条真的能走的替代路','入口这次撤下，过去的见闻单独留存，没有继续推荐一个目前进不去的目的地。','你们实际确认了替代路；旧路线被清楚标成历史注记，两个版本没有混成同一次旅行。'],
  ['并排记录里多了一个问号','分头验证的设备记录出现第三种结果。零点不想继续平均，凛也承认自己的听感不能代替别人。{guest}把设置原样抄过来，请你们先留下这个问号。','把第三种情况作为未验证条目保留','只交换复现步骤，不继续扩大这版路线卡','问号被写进记录，原有两种结果没有被撤成错误，也没有新造一个万能结论。','你们留下可复现的步骤，这版卡片没有继续加长；新的验证等真正有人有余力时再开始。'],
 ],
 renewal:[
  ['角落里只挪了一张椅子','缩小范围后只挪一张椅子，小满却突然觉得空出的地方太大。弥生想先摆个新东西，{guest}提出也许可以先空一晚。这个角落不需要当天证明已经重新变好。','先让这个位置空着，观察今天怎么使用','摆一件与旧用途不同的小物，保留旧版记录','空位真的留了一晚，没有被强行填成一个完成象征。小满后来讲起坐在另一侧时看到的新视角。','新物件有自己的用途，旧版仍单独保存；这次摆放没有被解释成任何旧关系已经和解。'],
  ['另存以后仍会打开旧版','另存的新版本完成一部分，小满还是会点开旧页。弥生担心她又整晚停在那里，{guest}却说偶尔回看也未必意味着不愿继续。今晚时间只够选一种安排。','回看一页就停，把新版本留到明天','今天先用新版本，旧页仍单独保存','你们只看了一页，到约好的结束点就收好。新版本没在这晚推进，旧记忆也没有被要求删掉。','新版本真的被使用了一次，旧页没有被覆盖，也没人靠检查别人是否回看来判定放下。'],
  ['两件新作有相似的折角','分头做的新作品出现同一个折角。弥生想再改，小满觉得它已经有新的用途。{guest}仔细看过两件东西，发现相似的只是轮廓，里面装的早就不同。','保留折角，具体标明各自的新用途','另改一个版本作比较，不覆盖已经做好的那份','折角保留下来，两件作品分别署名、分别使用，没有被拼成一份共同答案。','比较版另外保存，原版仍能打开；变化是一次实际尝试，没有承担证明谁已经彻底放下的任务。'],
 ],
};
const GUESTS={quiet:'mika',workshop:'ash',gathering:'yuki',letters:'rei',paths:'raina',renewal:'lin'};
export const TURN_SCENES=Object.keys(TURNS).flatMap(theme=>[0,1,2].map(variant=>({id:`turn-${theme}-${variant}`,theme,variant})));
export function turnReady(run,q){const s=TURN_SCENES.find(s=>s.id===q.id),e=run.encore,t=s&&THEMES.find(t=>t.id===s.theme);return !!t&&e.route===t.id&&e.days.length>=2&&e.choices[1]===s.variant&&e.detour===null&&run.day>=e.days[1]+2&&q.npc===t.cast[0]&&q.other===t.cast[1]&&t.cast.every(id=>run.relationships[id].introduced&&!departureContactReason(run,id));}
export function turnMessages(run){return TURN_SCENES.map(s=>{const t=THEMES.find(t=>t.id===s.theme);return {type:'scene',id:s.id,npc:t.cast[0],other:t.cast[1],optional:true};}).filter(q=>turnReady(run,q));}
export function turnScene(run,q){const s=TURN_SCENES.find(s=>s.id===q.id);if(!s)return null;const row=TURNS[s.theme][s.variant],id=GUESTS[s.theme],guest=run.relationships[id].introduced&&!departureContactReason(run,id)?id:null;return {id:s.id,npc:q.npc,other:q.other,cast:[q.npc,q.other,...(guest?[guest]:[])],title:row[0],subtitle:'旅程主题 · 另一件确实发生的小事',text:(run.encore.days.length===3?'主题收工后，又有这段近况补了过来。\n\n':'')+row[1].replaceAll('{guest}',guest?PEOPLE.find(p=>p.id===guest).name:'一位同行的朋友'),choices:[0,1].map(i=>({label:row[2+i],text:row[4+i],effects:i?{balance:2,mood:-1}:{energy:-3,mood:2},rel:{trust:2},otherRel:{trust:2},...(guest?{castRel:{[guest]:{trust:1}}}:{}),outcome:'theme-turn-read',variant:s.variant}))};}
export function resolveTurn(run,c,index){run.encore.detour={variant:c.variant,choice:index,day:run.day};}
export function validTurn(run){const e=run.encore,d=e.detour;if(d===null)return true;return !!d&&[0,1,2].includes(d.variant)&&[0,1].includes(d.choice)&&e.days.length>=2&&d.variant===e.choices[1]&&Number.isInteger(d.day)&&d.day>=e.days[1]+2&&d.day<=run.day&&run.storySeen.includes(`turn-${e.route}-${d.variant}`);}
